        // and lock contention on catalog tables can cause delays.
        dbContext.Database.SetCommandTimeout(TimeSpan.FromSeconds(_schemaCommandTimeoutSeconds));
        try {
          var steps = new Whizbang.Data.EFCore.Postgres.SchemaStepRunner(
            dbContext, lockId, "__SCHEMA__", ct => _isSchemaCurrentAsync(connection, ct), serviceProvider, logger,
            TimeProvider.System) {
            RetryDelayFor = ex => {
              // A failed step says whether the initializer will retry, and when: the delay is decided here and the
              // retry below waits exactly that long.
              if (!_isRetryableError(ex)) {
                return null;
              }
              plannedRetryDelay = _initializationRetryDelay(retryAttempt + 1, rng);
              return plannedRetryDelay;
            },
          };

          var pass = await _beginPassAsync(
            steps, connection, duplicateSweepPending || staleDefinitionSweepPending, logger, cancellationToken);
          if (pass is null) {
            // Nothing owed: another instance finished while this one waited, or before it took the lock.
            if (logger is not null) {
              Whizbang.Data.EFCore.Postgres.SchemaInitializationLog.SchemaInitializedByOtherInstance(logger, "__SCHEMA__");
            }
            await Whizbang.Data.Postgres.SchemaInitializationStages.MigrationNotNeededAsync(
              serviceProvider, "another instance migrated the schema", cancellationToken);
            break;
          }

          logger?.LogInformation("Starting database initialization for {DbContext} (schema: __SCHEMA__, infra={InfraChanged}, persp={PerspChanged})...",
            "__DBCONTEXT_CLASS__", pass.Infra, pass.Persp);
          steps.BeginPass(pass.TotalSteps);
          await Whizbang.Data.Postgres.SchemaInitializationStages.ApplyingAsync(serviceProvider, pass.TotalSteps, cancellationToken);

          // Step 1: core infrastructure tables (Inbox, Outbox, EventStore, etc.)
          phaseSw.Restart();
          var coreRan = await _runRecordedStepAsync(steps, connection, pass, _coreStep,
            ct => ExecuteCoreInfrastructureTablesAsync(dbContext, logger, ct), cancellationToken);
          phases.Add(("CoreInfrastructure", phaseSw.ElapsedMilliseconds, coreRan ? "completed" : "skipped (hash match)"));

          // Step 2: each migration file, with its ledger row in the same transaction. Before the perspectives, so the
          // tracking tables and functions they use exist.
          phaseSw.Restart();
          migrationsApplied = await ExecuteMigrationsAsync(dbContext, steps, pass, logger, cancellationToken);
          phases.Add(("Migrations", phaseSw.ElapsedMilliseconds, pass.Infra ? "completed" : "skipped (hash match)"));

          // Step 3: a model whose table name changed has its table renamed in place, before the next step creates
          // the new name as an empty table (#1719).
          phaseSw.Restart();
          var renamesRan = await _runRecordedStepAsync(steps, connection, pass, _perspectiveRenamesStep,
            ct => FollowPerspectiveTableRenamesAsync(connection, logger, ct), cancellationToken);
          phases.Add(("PerspectiveRenames", phaseSw.ElapsedMilliseconds, renamesRan ? "completed" : "skipped (hash match)"));

          // Step 3b: each perspective table, hash-tracked one by one.
          phaseSw.Restart();
          await ExecutePerspectiveTablesAsync(dbContext, steps, pass, segmentConnectionFactory, logger, cancellationToken);
          phases.Add(("PerspectiveTables", phaseSw.ElapsedMilliseconds, pass.RunPerspectives ? "completed" : "skipped (hash match)"));

          // Step 4: constraints (composite PKs, FKs) that TableDefinition doesn't support yet.
          phaseSw.Restart();
          var constraintsRan = await _runRecordedStepAsync(steps, connection, pass, _constraintsStep,
            ct => ExecuteConstraintsAsync(dbContext, logger, ct), cancellationToken);
          phases.Add(("Constraints", phaseSw.ElapsedMilliseconds, constraintsRan ? "completed" : "skipped (hash match)"));

          // Step 5: perspective associations (wh_message_associations, for event routing), then the associations-set hash, so
          // adding or removing an Apply(TEvent) method re-registers even when no table changed.
          phaseSw.Restart();
          var associationsRan = await _runRecordedStepAsync(steps, connection, pass, _associationsStep, async _ => {
            #region REGISTER_ASSOCIATIONS
            #endregion
            await _recordAssociationsHashAsync(connection, pass, cancellationToken);
          }, cancellationToken);
          phases.Add(("Associations", phaseSw.ElapsedMilliseconds, associationsRan ? "completed" : "skipped (hash match)"));

          // Step 6: the perspective registry (CLR type → table name, for drift detection) and the message type registry
          // (pinned ids and CLR type names).
          phaseSw.Restart();
          var registriesRan = await _runRecordedStepAsync(steps, connection, pass, _registriesStep, async ct => {
            await ReconcilePerspectiveRegistryAsync(dbContext, logger, ct);
            await ReconcileMessageTypeRegistryAsync(dbContext, serviceProvider, logger, ct);
          }, cancellationToken);
          phases.Add(("Registries", phaseSw.ElapsedMilliseconds, registriesRan ? "completed" : "skipped (hash match)"));

          if (steps.CompletedElsewhere) {
            // Another instance finished the pass while this one waited for a step's lock; its commits serve this one.
            await Whizbang.Data.Postgres.SchemaInitializationStages.MigrationNotNeededAsync(
              serviceProvider, "another instance finished the pass", cancellationToken);
            break;
          }
          steps.CompletePass();

          sw.Stop();
          var phaseSummary = string.Join(", ", phases.Select(p => $"{p.Name}={p.Ms}ms({p.Status})"));
          logger?.LogInformation(
            "Database initialization complete for {DbContext} — {MigrationsApplied} migration(s) in {ElapsedMs}ms [{Phases}]",
            "__DBCONTEXT_CLASS__", migrationsApplied, sw.ElapsedMilliseconds, phaseSummary);

          // Clear all Npgsql connection pools after migrations complete.
          // CREATE OR REPLACE FUNCTION assigns new OIDs to functions, but connections
          // already in the pool still cache the old OIDs. Clearing pools forces new
          // connections with correct OID mappings. This only runs once at startup.
          Npgsql.NpgsqlConnection.ClearAllPools();
          logger?.LogDebug("Cleared Npgsql connection pools to refresh function OID mappings");
        } finally {
          // Reset command timeout to default
          try { dbContext.Database.SetCommandTimeout(null); } catch { /* best effort */ }
        }

        break; // Success — exit outer retry loop
      } catch (Exception ex) when (_isRetryableError(ex)) {
        retryAttempt++;
        // Exponential backoff: 1s, 2s, 4s, 8s, 16s, 32s, 64s, 128s, 180s cap + jitter. A failed step already said
        // when the retry would come, and it comes then.
        var totalDelay = plannedRetryDelay ?? _initializationRetryDelay(retryAttempt, rng);
        plannedRetryDelay = null;

        if (logger is not null) {
          Whizbang.Data.EFCore.Postgres.SchemaInitializationLog.InitializationRetry(logger, "__SCHEMA__", retryAttempt, (int)totalDelay.TotalMilliseconds, ex.Message);
        }

        // A transient failure can leave a DEAD transaction enlisted on the context — rolling back
        // over a broken connection is itself best-effort. The next attempt must never inherit it:
        // EF routes its first operation through the retrying execution strategy, whose
        // OnFirstExecution refuses to start inside a user-initiated transaction — which would turn
        // this TRANSIENT outage into a PERMANENT init failure (observed live: a connection-slot
        // exhaustion became a never-ready pod).
        try {
          if (dbContext.Database.CurrentTransaction is not null) {
            await dbContext.Database.UseTransactionAsync(null, CancellationToken.None);
          }
        } catch { /* discarding a dead enlistment is best-effort by definition */ }

        // Reset state for retry
        phases.Clear();
        migrationsApplied = 0;
        sw.Restart();

        await Task.Delay(totalDelay, cancellationToken);
      } finally {
        // Close the explicitly-opened connection (returns to pool)
        try {
          await dbContext.Database.CloseConnectionAsync();
        } catch (Exception ex) {
          if (logger is not null) {
            Whizbang.Data.EFCore.Postgres.SchemaInitializationLog.FailedToCloseConnection(logger, ex, "__SCHEMA__");
          }
        }
      }
    }

    // The tables the pass created an index on are analyzed now that it has committed, so the planner
    // has statistics for each new index's expression rather than a default that can make it ignore the
    // index until autovacuum next analyzes the table (#1004). Outside the transaction and the lock, and
    // never fatal: a table left unanalyzed is found by the maintenance step.
    await Whizbang.Data.Postgres.SchemaInitializationStages.ConvergingAsync(serviceProvider, cancellationToken);
    await _analyzeNewlyIndexedTablesAsync(dbContext, segmentConnectionFactory, logger, cancellationToken);

    // The managed-object reconcile runs at every start, the fast path included: an object retired by a release
    // whose schema hash did not change, or dropped by hand, is found by reading the catalog, not the hash. After
    // the commit, on a connection of its own, because DROP INDEX CONCURRENTLY cannot run in a transaction.
    await _reconcileManagedObjectsAsync(dbContext, reconcileSettings, segmentConnectionFactory, serviceProvider, logger, cancellationToken);

    // Each perspective table's fillfactor and autovacuum settings follow its model at every start, the fast path
    // included, except on the tables listed in perspective_storage_manual_tables (#1747). One catalog read; a table
    // already in line is not altered. Never fatal.
    await Whizbang.Data.EFCore.Postgres.PerspectiveStorageReconcile.RunAsync(
      dbContext, "__SCHEMA__", System.Linq.Enumerable.Select(GetPerspectiveEntries(), e => e.Sql), segmentConnectionFactory,
      logger, cancellationToken);

    // No maintenance here (#1351). Schema initialization runs on every instance at every start, and a
    // service that scales out on its backlog starts instances at the peak of a load: the purge runs in
    // the maintenance cycle behind its busy check, and the work tables are vacuumed by the instance that
    // acquires the maintainer duty (WorkTableVacuumOnAcquisition), on the table owner's connection.
  }

  /// <summary>
  /// Determines if an exception is transient and the initialization should be retried.
  /// </summary>
  internal static bool _isRetryableError(Exception ex) {
    if (ex is Npgsql.NpgsqlException npgsqlEx) {
      if (npgsqlEx.IsTransient) return true;
      if (npgsqlEx is Npgsql.PostgresException pgEx) {
        // 40001 = serialization_failure, 40P01 = deadlock_detected, 57014 = query_canceled (timeout)
        return pgEx.SqlState is "40001" or "40P01" or "57014";
      }
    }
    if (ex is TimeoutException) return true;
    if (ex is System.IO.IOException) return true;
    return false;
  }

  /// <summary>
  /// Names of framework-defined functions that currently have MORE THAN ONE overload in the
  /// schema. Before drop_all_overloads resolved its own schema (it filtered by current_schema(),
  /// which pooled EF connections reduce to 'public'), every signature change in a multi-schema
  /// deployment silently left the old overload behind. Duplicates make unqualified calls ambiguous
  /// and the next return-type change fail with 42P13, so the initializer sweeps them by forcing
  /// the defining migrations to re-run — their (fixed) drop_all_overloads clears every overload
  /// and the file recreates the single canonical one. The intersection with extracted migration
  /// object names keeps a consumer's own intentional overloads from ever triggering this.
  /// </summary>
  private static async Task<System.Collections.Generic.HashSet<string>> _getDuplicateFrameworkOverloadNamesAsync(
      Npgsql.NpgsqlConnection connection, CancellationToken ct) {
    var duplicates = new System.Collections.Generic.HashSet<string>(StringComparer.Ordinal);
    await using (var cmd = connection.CreateCommand()) {
      cmd.CommandText = @"
        SELECT p.proname FROM pg_proc p
        JOIN pg_namespace n ON p.pronamespace = n.oid
        WHERE n.nspname = @schema
        GROUP BY p.proname HAVING COUNT(*) > 1";
      var schemaName = "__SCHEMA__";
      cmd.Parameters.AddWithValue("schema", string.IsNullOrEmpty(schemaName) ? "public" : schemaName);
      cmd.CommandTimeout = 30;
      await using var reader = await cmd.ExecuteReaderAsync(ct);
      while (await reader.ReadAsync(ct)) {
        duplicates.Add(reader.GetString(0));
      }
    }
    if (duplicates.Count == 0) {
      return duplicates;
    }
    var frameworkNames = new System.Collections.Generic.HashSet<string>(StringComparer.Ordinal);
    foreach (var (name, sql) in GetMigrationScripts()) {
      foreach (var obj in Whizbang.Data.Postgres.MigrationObjectExtractor.Extract(_transformMigrationSql(sql, "__SCHEMA__")).Objects) {
        frameworkNames.Add(obj);
      }
    }
    duplicates.IntersectWith(frameworkNames);
    return duplicates;
  }

  /// <summary>
  /// Returns the migration files whose last-word function definitions are not what the database holds:
  /// a deployed body that differs from the last-word body, or a framework function that is missing.
  /// Bodies are compared whitespace-normalized (the embedded runner indents the file text). Functions
  /// with more than one overload are left to the duplicate-overload sweep. Logs one Information line per
  /// stale file naming the functions that made it stale.
  /// </summary>
  /// <summary>
  /// Renders the embedded migration text the way <c>ExecuteSqlRawAsync</c> renders it: the generator
  /// doubles every brace so the text survives format-string handling, and the server receives single
  /// braces. Comparisons against deployed bodies must see the single-brace form.
  /// </summary>
  /// <summary>
  /// <summary>
  /// Runs one migration body, sending any batched region repeatedly until it changes no rows.
  /// </summary>
  /// <remarks>
  /// <para>
  /// A migration is normally one command, which is why a statement that rewrites every row of a
  /// large table cannot finish: the whole file shares one command timeout, and a loop written inside
  /// the SQL does not help because a DO block is still one command. A marked region is sent on its
  /// own instead, once per batch, so each send carries its own budget and the bound that matters is
  /// rows per send rather than how long the table takes.
  /// </para>
  /// <para>
  /// The loop ends when a send reports no rows, which is the only signal that needs no extra query
  /// and cannot disagree with the work actually done. A region whose statement does not shrink its
  /// own candidate set would never report zero, so the iteration cap turns that into a named failure
  /// rather than a service that never starts — the same outcome as today, but explained.
  /// </para>
  /// </remarks>
  private static async Task _executeMigrationBodyAsync(
      Microsoft.EntityFrameworkCore.DbContext dbContext,
      string sql,
      string migrationName,
      Microsoft.Extensions.Logging.ILogger? logger,
      System.Threading.CancellationToken cancellationToken) {
    var segments = Whizbang.Data.Postgres.MigrationBatchRegions.Segment(sql);

    // The migration runs with current_schema() resolving to the schema it migrates, and only the
    // migration: shipped guards compare table_schema = current_schema(), and shipped files are never
    // edited, so this is what makes a re-run on upgrade find what the earlier run created. Restored
    // after, because the same transaction goes on to the next migration and the perspective DDL.
    var migrationConnection = (Npgsql.NpgsqlConnection)dbContext.Database.GetDbConnection();
    var previousSearchPath = await Whizbang.Data.Postgres.MigrationSearchPath.EnterAsync(
      migrationConnection, "__SCHEMA__", cancellationToken);

    // The overwhelming majority of migrations carry no marker and come back as one plain segment. Its idempotent DDL
    // is catalog-checked as it is sent (#1636): an ADD COLUMN or CREATE INDEX IF NOT EXISTS with nothing to do takes
    // no lock, so a re-run does not queue behind, or deadlock with, the workers using the table.
    foreach (var segment in segments) {
      if (segment.Kind == Whizbang.Data.Postgres.MigrationSegmentKind.Plain) {
        await dbContext.Database.ExecuteSqlRawAsync(Whizbang.Data.Postgres.CatalogCheckedDdl.Guard(segment.Sql), cancellationToken);
        continue;
      }

      var pass = 0;
      long totalRows = 0;
      while (true) {
        cancellationToken.ThrowIfCancellationRequested();

        // A batched region reports how many rows it handled, rather than the runner reading rows
        // affected. Two reasons, both load-bearing. A backfill often has to be guarded — on a replay
        // the column it rewrites may no longer exist — and a guard needs a function body, which a
        // bare DML statement cannot carry. And a function can do several statements that see each
        // other's effects, which a single statement's CTEs cannot: a CTE reads the snapshot, so an
        // UPDATE in one arm cannot see rows an INSERT in another arm just wrote.
        var rows = await _scalarRowCountAsync(dbContext, segment.Sql, migrationName, cancellationToken);
        if (rows <= 0) {
          break;
        }

        pass++;
        totalRows += rows;
        logger?.LogDebug(
          "Migration {Migration}: batch {Pass} moved {Rows} row(s) ({Total} so far)",
          migrationName, pass, rows, totalRows);

        if (pass >= MAX_BATCH_PASSES) {
          throw new InvalidOperationException(
            $"Migration {migrationName} ran {pass} batches of {segment.BatchSize} without finishing "
            + $"({totalRows} rows so far). A batch has to exclude the rows it already handled, or it "
            + "reports the same rows forever; check the region's WHERE clause.");
        }
      }

      if (pass > 0) {
        logger?.LogInformation(
          "Migration {Migration}: backfilled {Total} row(s) in {Passes} batch(es) of {Size}",
          migrationName, totalRows, pass, segment.BatchSize);
      }
    }

    await Whizbang.Data.Postgres.MigrationSearchPath.ExitAsync(migrationConnection, previousSearchPath, cancellationToken);
  }

  /// <summary>
  /// Runs one pass of a batched region and reads the row count it reports.
  /// </summary>
  /// <remarks>
  /// The region's statement returns a single whole number: how many rows this pass handled. Zero
  /// ends the loop. A region that returns nothing at all is a defect in the migration rather than a
  /// finished backfill, and is reported as such instead of being read as "done" — that reading would
  /// skip the backfill silently and leave the table half migrated.
  /// </remarks>
  private static async Task<long> _scalarRowCountAsync(
      Microsoft.EntityFrameworkCore.DbContext dbContext,
      string sql,
      string migrationName,
      System.Threading.CancellationToken cancellationToken) {
    var connection = dbContext.Database.GetDbConnection();
    await using var cmd = connection.CreateCommand();
    cmd.CommandText = sql;
    cmd.CommandTimeout = _schemaCommandTimeoutSeconds;
    if (dbContext.Database.CurrentTransaction is not null) {
      cmd.Transaction = dbContext.Database.CurrentTransaction.GetDbTransaction();
    }

    var result = await cmd.ExecuteScalarAsync(cancellationToken);
    if (result is null || result is DBNull) {
      throw new InvalidOperationException(
        $"Migration {migrationName} has a batched region that returned no value. A batched region "
        + "has to report the number of rows it handled, so the runner knows whether to send it "
        + "again; it is normally 'SELECT <schema>.some_backfill(@whizbang_batch_size);'.");
    }

    return System.Convert.ToInt64(result, System.Globalization.CultureInfo.InvariantCulture);
  }

  /// <summary>
  /// How many batches one marked region may run before it is treated as not converging.
  /// </summary>
  /// <remarks>
  /// At the default size this is a hundred million rows, far past any real backfill, so reaching it
  /// means the statement is not excluding what it already did rather than that the table is large.
  /// </remarks>
  private const int MAX_BATCH_PASSES = 10_000;

  /// <summary>
  /// The timeout of the initialization in progress, set once at its start. Flows into every helper
  /// it awaits and reverts when it returns, so concurrent initializations keep their own.
  /// </summary>
  private static readonly System.Threading.AsyncLocal<int?> _schemaCommandTimeout = new();

  /// <summary>
  /// How long any one schema statement may take: the initialization connection string's
  /// <c>Command Timeout</c> when it sets one, otherwise ten minutes.
  /// </summary>
  /// <remarks>
  /// A rewrite of a stored format is one statement over every row of a table, which legitimately
  /// takes far longer than an ordinary command, and a schema pass that gives up half way leaves the
  /// service unable to start. One value because both the EF path and the boundary path need it to
  /// be the same number.
  /// </remarks>
  private static int _schemaCommandTimeoutSeconds =>
    _schemaCommandTimeout.Value ?? Whizbang.Data.Postgres.SchemaCommandTimeout.DEFAULT_SECONDS;

  private static string _renderFormatBraces(string sql) => sql.Replace("{{", "{").Replace("}}", "}");

  /// <summary>
  /// Whether the schema needs nothing applied to it, asked without taking a lock.
  /// </summary>
  /// <remarks>
  /// <para>
  /// The same three questions the fast path asks, and it has to be all three. Hashes describe the
  /// files rather than the database, so they cannot see a stale duplicate overload left behind by an
  /// older drop, nor a function body an out-of-order replay reverted to an earlier definition. An
  /// instance that waited on hashes alone would stop waiting while the work it was waiting for was
  /// still outstanding.
  /// </para>
  /// <para>
  /// Quiet about what it finds, because it runs repeatedly while waiting on another instance and
  /// the fast path's once-per-startup logging would become a stream. A failure is raised rather
  /// than swallowed, and the caller decides what it means: on an empty database the tracking tables
  /// this reads are themselves created by the migration being waited for, so the first answer being
  /// unavailable is ordinary. What it must never do is report "current" because it could not tell.
  /// </para>
  /// </remarks>
  private static async Task<bool> _isSchemaCurrentAsync(
      Npgsql.NpgsqlConnection connection, CancellationToken cancellationToken) {
    try {
      var hashes = await _bulkGetHashesAsync(connection, cancellationToken);
      var (infraChanged, perspChanged, associationsChanged) = _compareHashes(hashes);
      if (infraChanged || perspChanged || associationsChanged) {
        return false;
      }

      if ((await _getDuplicateFrameworkOverloadNamesAsync(connection, cancellationToken)).Count > 0) {
        return false;
      }

      var stale = await _getStaleFunctionDefinitionFilesAsync(
        connection, GetMigrationScripts(), null, cancellationToken);
      return stale.Count == 0;
    } catch (Exception ex) when (ex is not OperationCanceledException) {
      // Unanswerable is not the same as current. Reported by the caller, which knows whether this
      // was the expected first answer or a genuine problem.
      throw new InvalidOperationException(
        "Could not determine whether schema __SCHEMA__ is current", ex);
    }
  }

  /// <summary>
  /// Applies schema SQL, committing wherever the generator marked a boundary.
  /// </summary>
  /// <remarks>
  /// <para>
  /// Most schema SQL belongs in the initializer's transaction, so SQL carrying no boundary is
  /// applied exactly as before. A boundary says one statement can only see an earlier one's effect
  /// once that earlier one has committed, which a single transaction cannot provide: an index over
  /// an expression is built by evaluating it on every heap tuple that is not yet dead, and the row
  /// version an uncommitted rewrite superseded is still live.
  /// </para>
  /// <para>
  /// Applied on its own connection, so each piece commits and a rewrite that has succeeded survives
  /// a later failure in the same pass. Without that the rollback undoes the rewrite along with the
  /// statement that failed, and every retry starts from the state that just failed. Instances stay
  /// mutually excluded because this runs only while the caller holds the initialization lock.
  /// </para>
  /// </remarks>
  private static async Task _applySchemaSqlAsync(
      Microsoft.EntityFrameworkCore.DbContext dbContext,
      Func<Npgsql.NpgsqlConnection>? segmentConnectionFactory,
      string sql,
      ILogger? logger,
      CancellationToken cancellationToken) {
    if (Whizbang.Data.Postgres.OptionalExtensionBlocks.HasBlocks(sql)) {
      // A block of indexes that need an extension the server may refuse. Applied as one batch, a
      // refused CREATE EXTENSION fails the whole pass; the reader creates the extension under a
      // savepoint, skips the block with one warning when the server refuses it, and applies the
      // rest, so a service runs without that index family rather than without a schema.
      var extensionConnection = (Npgsql.NpgsqlConnection)dbContext.Database.GetDbConnection();
      var extensionTransaction = dbContext.Database.CurrentTransaction?.GetDbTransaction() as Npgsql.NpgsqlTransaction;
      await Whizbang.Data.Postgres.OptionalExtensionBlocks.ApplyAsync(
        extensionConnection, extensionTransaction, _renderFormatBraces(sql), _schemaCommandTimeoutSeconds, logger, cancellationToken);
      return;
    }

    if (!sql.Contains(Whizbang.Data.Postgres.SchemaCommandBoundary.MARKER, StringComparison.Ordinal)) {
      await dbContext.Database.ExecuteSqlRawAsync(sql, cancellationToken);
      return;
    }

    if (segmentConnectionFactory is null) {
      // Nothing to open a second connection with: no initialization string, no data source in the
      // container, and no configured string either. Applying the script whole is what this exists
      // to avoid, so it is said out loud: every new database succeeds either way, because there are
      // no rows to rewrite, and one carrying rows written in an older format fails until a
      // connection can be had.
      logger?.LogWarning(
        "Schema SQL for {Schema} needs a commit boundary but no connection can be opened to apply "
        + "it across one, so it is being applied whole. A rewrite of a stored format cannot commit "
        + "before the index built over it, so a database holding rows in the older format will fail "
        + "to migrate. Pass an initialization connection string, or register an NpgsqlDataSource.",
        "__SCHEMA__");
      await dbContext.Database.ExecuteSqlRawAsync(sql, cancellationToken);
      return;
    }

    // ExecuteSqlRawAsync reads its argument as a format string and un-doubles the braces the
    // generator doubled. Going around it means doing that here, or a brace arrives literally.
    await Whizbang.Data.Postgres.SchemaCommandBoundary.ApplyAsync(
      segmentConnectionFactory,
      _renderFormatBraces(sql),
      _schemaCommandTimeoutSeconds,
      logger,
      cancellationToken);
  }

  private static async Task<System.Collections.Generic.IReadOnlyList<string>> _getStaleFunctionDefinitionFilesAsync(
      Npgsql.NpgsqlConnection connection,
      (string Name, string Sql)[] migrations,
      ILogger? logger,
      CancellationToken ct) {
    // Compare what the database HOLDS with what the migration EXECUTES. The embedded text carries
    // doubled braces because ExecuteSqlRawAsync treats it as a format string and un-doubles them on
    // the way to the server; a comparison on the embedded text would report every function whose
    // body contains a brace as stale, on every boot.
    var lastWords = Whizbang.Data.Postgres.MigrationFunctionBodies.LastWord(
      migrations.Select(m => (m.Name, _renderFormatBraces(_transformMigrationSql(m.Sql, "__SCHEMA__")))));
    if (lastWords.Count == 0) {
      return System.Array.Empty<string>();
    }

    var deployed = new System.Collections.Generic.Dictionary<string, System.Collections.Generic.IReadOnlyList<string>>(StringComparer.Ordinal);
    await using (var cmd = connection.CreateCommand()) {
      cmd.CommandText = @"
        SELECT p.proname, p.prosrc FROM pg_proc p
        JOIN pg_namespace n ON p.pronamespace = n.oid
        WHERE n.nspname = @schema AND p.proname = ANY(@names)";
      var schemaName = "__SCHEMA__";
      cmd.Parameters.AddWithValue("schema", string.IsNullOrEmpty(schemaName) ? "public" : schemaName);
      cmd.Parameters.AddWithValue("names", lastWords.Keys.ToArray());
      cmd.CommandTimeout = 30;
      await using var reader = await cmd.ExecuteReaderAsync(ct);
      while (await reader.ReadAsync(ct)) {
        var proname = reader.GetString(0);
        var prosrc = reader.IsDBNull(1) ? "" : reader.GetString(1);
        if (!deployed.TryGetValue(proname, out var bodies)) {
          bodies = new System.Collections.Generic.List<string>();
          deployed[proname] = bodies;
        }
        ((System.Collections.Generic.List<string>)bodies).Add(prosrc);
      }
    }

    var staleFunctionsByFile = new System.Collections.Generic.Dictionary<string, System.Collections.Generic.List<string>>(StringComparer.Ordinal);
    var files = Whizbang.Data.Postgres.MigrationFunctionBodies.FilesToRerun(lastWords, deployed, staleFunctionsByFile);
    foreach (var file in files) {
      logger?.LogInformation(
        "Migration {Migration}: re-running because the database's definition of {Functions} does not match this file, its last word. A replay that predates the redefinition closure left the function on an earlier definition while every hash read unchanged.",
        file, string.Join(", ", staleFunctionsByFile[file]));
    }
    return files;
  }

  /// <summary>
  /// Bulk-queries all per-object hashes from wh_schema_migrations.
  /// Used by the fast path to detect changes without acquiring a lock.
  /// </summary>
  private static async Task<System.Collections.Generic.List<(string FileName, string Hash, string Owner, string? AppliedBy, short Status)>> _bulkGetHashesAsync(
      Npgsql.NpgsqlConnection connection, CancellationToken ct) {
    await using var cmd = connection.CreateCommand();
    // The joined library_version is what lets the applier tell an upgrade from a downgrade —
    // the content hash alone only says "different", never which side is newer.
    cmd.CommandText = @"
      SELECT m.file_name, m.content_hash, m.owner, v.library_version, m.status
      FROM __QUOTED_SCHEMA__.wh_schema_migrations m
      LEFT JOIN __QUOTED_SCHEMA__.wh_schema_versions v ON v.id = m.version_id";
    cmd.CommandTimeout = 30;
    var results = new System.Collections.Generic.List<(string, string, string, string?, short)>();
    await using var reader = await cmd.ExecuteReaderAsync(ct);
    while (await reader.ReadAsync(ct)) {
      var owner = reader.IsDBNull(2) ? "whizbang" : reader.GetString(2);
      var appliedBy = reader.IsDBNull(3) ? null : reader.GetString(3);
      results.Add((reader.GetString(0), reader.GetString(1), owner, appliedBy, reader.GetInt16(4)));
    }
    return results;
  }

  /// <summary>
  /// Compares existing per-object hashes against build-time hashes.
  /// Partitions by owner column to determine infrastructure vs perspective vs association changes independently.
  /// </summary>
  private static (bool InfraChanged, bool PerspChanged, bool AssociationsChanged) _compareHashes(
      System.Collections.Generic.List<(string FileName, string Hash, string Owner, string? AppliedBy, short Status)> existingRows) {
    var infraHashes = new System.Collections.Generic.Dictionary<string, (string Hash, string? AppliedBy)>();
    var perspHashes = new System.Collections.Generic.Dictionary<string, (string Hash, string? AppliedBy)>();
    var associationHashes = new System.Collections.Generic.Dictionary<string, (string Hash, string? AppliedBy)>();
    // A step this context's pass still owes (a pass part way through, here or on another instance) is a change like
    // any other: the slow path resumes it.
    var stepsOutstanding = false;
    foreach (var (fileName, hash, owner, appliedBy, status) in existingRows) {
      if (owner == Whizbang.Data.Postgres.SchemaPassLedger.STEP_OWNER) {
        stepsOutstanding |= fileName.StartsWith(_stepKeyPrefix, StringComparison.Ordinal)
          && Whizbang.Data.Postgres.SchemaPassLedger.IsOutstanding(status);
      } else if (owner == "perspective") {
        perspHashes[fileName] = (hash, appliedBy);
      } else if (owner == "association") {
        associationHashes[fileName] = (hash, appliedBy);
      } else {
        infraHashes[fileName] = (hash, appliedBy);
      }
    }

    // Compare infrastructure migrations
    var infraChanged = stepsOutstanding;
    var migrations = GetMigrationScripts();
    foreach (var (name, sql) in migrations) {
      var hash = _migrationHash(_transformMigrationSql(sql, "__SCHEMA__"));
      if (!infraHashes.TryGetValue(name, out var existing)) {
        infraChanged = true;
        break;
      }
      // A hash that differs but was written by a NEWER build is not work this instance can do.
      // Reporting it as changed would send this instance down the slow path to take the advisory
      // lock and then do nothing — delaying the instance that can actually migrate.
      if (existing.Hash != hash
          && Whizbang.Data.Postgres.MigrationVersionGuard.MayApply("__LIBRARY_VERSION__", existing.AppliedBy, out _)) {
        infraChanged = true;
        break;
      }
    }

    // Compare perspective entries
    var perspChanged = false;
    var perspectives = GetPerspectiveEntries();
    foreach (var (name, sql) in perspectives) {
      var key = $"perspective:{name}";
      var hash = Convert.ToHexStringLower(
          System.Security.Cryptography.SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(sql)));
      if (!perspHashes.TryGetValue(key, out var existing)) {
        perspChanged = true;
        break;
      }
      if (existing.Hash != hash
          && Whizbang.Data.Postgres.MigrationVersionGuard.MayApply("__LIBRARY_VERSION__", existing.AppliedBy, out _)) {
        perspChanged = true;
        break;
      }
    }

    // Compare the perspective-association set hash. Missing row (first run or pre-hash DBs)
    // or mismatched hash both count as changed. Skip entirely when this DbContext has no
    // associations (empty hash) to avoid tripping on no-op.
    var associationsChanged = false;
    if (_associationsHash.Length > 0) {
      if (!associationHashes.TryGetValue(_associationsHashKey, out var existingAssoc)) {
        associationsChanged = true;
      } else if (existingAssoc.Hash != _associationsHash
          && Whizbang.Data.Postgres.MigrationVersionGuard.MayApply("__LIBRARY_VERSION__", existingAssoc.AppliedBy, out _)) {
        associationsChanged = true;
      }
    }

    return (infraChanged, perspChanged, associationsChanged);
  }

  /// <summary>
  /// Executes core infrastructure table DDL at runtime.
  /// Creates all Whizbang core tables: Inbox, Outbox, EventStore, ReceptorProcessing,
  /// PerspectiveCursors, RequestResponse, ServiceInstances, PartitionAssignments,
  /// MessageDeduplication, Sequences, and EventSequence.
  /// SQL is generated at runtime using PostgresSchemaBuilder.Instance.BuildInfrastructureSchema().
  /// AOT-compatible - no reflection or dynamic code generation, just string building.
  /// </summary>
  private static async Task ExecuteCoreInfrastructureTablesAsync(
    __DBCONTEXT_FQN__ dbContext,
    ILogger? logger,
    CancellationToken cancellationToken) {

    // Backward-compatibility: rename old table names before creating new ones.
    // Must happen before CREATE TABLE IF NOT EXISTS, otherwise the old table remains
    // orphaned and migration 033 fails with 42P07 (relation already exists).
    // Uses PL/pgSQL exception handling to avoid aborting the enclosing transaction
    // (PostgreSQL marks transactions as aborted after any unhandled error).
    const string BackwardCompatRenames = @"
DO $$
BEGIN
  ALTER TABLE IF EXISTS ""__SCHEMA__"".wh_perspective_checkpoints RENAME TO wh_perspective_cursors;
EXCEPTION WHEN duplicate_table OR undefined_table THEN NULL;
END $$;
DO $$
BEGIN
  ALTER INDEX IF EXISTS idx_perspective_checkpoints_perspective_name RENAME TO idx_perspective_cursors_perspective_name;
EXCEPTION WHEN undefined_object THEN NULL;
END $$;
DO $$
BEGIN
  ALTER INDEX IF EXISTS idx_perspective_checkpoints_last_event_id RENAME TO idx_perspective_cursors_last_event_id;
EXCEPTION WHEN undefined_object THEN NULL;
END $$;
";
    // Non-critical: logged and passed over (fresh databases won't have the old table), under a savepoint so a failure
    // here does not leave the step's transaction aborted for the tables after it.
    await _underSavepointAsync(
      (Npgsql.NpgsqlConnection)dbContext.Database.GetDbConnection(), "whizbang_compat_renames",
      () => dbContext.Database.ExecuteSqlRawAsync(BackwardCompatRenames, cancellationToken),
      ex => logger?.LogDebug(ex, "Backward-compat rename completed or skipped"), cancellationToken);

    // Generate schema SQL at runtime from C# definitions
    var schemaConfig = new SchemaConfiguration(
      InfrastructurePrefix: "wh_",
      PerspectivePrefix: "wh_per_",
      SchemaName: "__SCHEMA__"
    );
    var coreInfrastructureSchema = PostgresSchemaBuilder.Instance.BuildInfrastructureSchema(schemaConfig);

    try {
      // Catalog-checked (#1636): the ensure re-asserts every column and index on every pass, and each would otherwise
      // take its table's lock to find it already there.
      await dbContext.Database.ExecuteSqlRawAsync(
        Whizbang.Data.Postgres.CatalogCheckedDdl.Guard(coreInfrastructureSchema), cancellationToken);
      logger?.LogDebug("Core infrastructure tables created successfully");
    } catch (Exception ex) {
      logger?.LogError(ex, "Failed to create core infrastructure tables");
      throw;
    }
  }

  /// <summary>
  /// Applies the perspective tables, each in a step of its own with its ledger row (<c>perspective:&lt;table&gt;</c>)
  /// in the same transaction. An entry whose hash the pass found current is counted as skipped without taking the
  /// lock; one it found changed is re-checked under the lock, so an instance that finds another already applied it
  /// does nothing. A context with no per-perspective entries applies its whole script as one step.
  /// </summary>
  private static async Task ExecutePerspectiveTablesAsync(
    __DBCONTEXT_FQN__ dbContext,
    Whizbang.Data.EFCore.Postgres.SchemaStepRunner steps,
    SchemaPass pass,
    Func<Npgsql.NpgsqlConnection>? segmentConnectionFactory,
    ILogger? logger,
    CancellationToken cancellationToken) {

    var connection = (Npgsql.NpgsqlConnection)dbContext.Database.GetDbConnection();
    // Per-perspective SQL entries embedded by source generator
    var perspectiveEntries = GetPerspectiveEntries();

    if (perspectiveEntries.Length == 0) {
      // Backward compat: the whole perspective script as one step, recorded like the core tables.
      await _runRecordedStepAsync(steps, connection, pass, _perspectiveTablesStep, async ct => {
        const string PerspectiveTablesSchema = __PERSPECTIVE_TABLES_SCHEMA__;
        if (!string.IsNullOrWhiteSpace(PerspectiveTablesSchema)) {
          // __ENSURE_REQUIRED_EXTENSIONS__
          await _underSavepointAsync(connection, "whizbang_perspective_tables",
            () => _applySchemaSqlAsync(dbContext, segmentConnectionFactory, PerspectiveTablesSchema, logger, ct),
            ex => {
              if (ex is Npgsql.PostgresException { SqlState: "42P07" } existing) {
                logger?.LogDebug("Perspective tables already exist (expected): {Table}", existing.TableName ?? "unknown");
              } else {
                System.Runtime.ExceptionServices.ExceptionDispatchInfo.Throw(ex);
              }
            }, ct);
        }
      }, cancellationToken);
      return;
    }

    int executionOrder = 1000; // Start after infrastructure migrations
    foreach (var (name, sql) in perspectiveEntries) {
      executionOrder++;
      if (steps.CompletedElsewhere) {
        return;
      }
      var perspectiveKey = $"perspective:{name}";
      if (!pass.PerspectivesToRun.Contains(perspectiveKey)) {
        steps.Skip(perspectiveKey);
        continue;
      }

      var order = executionOrder;
      var hash = Convert.ToHexStringLower(
          System.Security.Cryptography.SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(sql)));
      string? existingHash = null;
      await steps.RunAsync(perspectiveKey,
        async ct => {
          if (!pass.Tracked) {
            return false;
          }
          existingHash = await _getExistingHashAsync(connection, perspectiveKey, ct);
          return existingHash == hash;
        },
        async ct => {
          if (pass.Tracked) {
            // Same rule as infrastructure migrations: an older build never overwrites a newer one's DDL.
            var perspAppliedBy = await _getExistingVersionAsync(connection, perspectiveKey, ct);
            if (!Whizbang.Data.Postgres.MigrationVersionGuard.MayApply("__LIBRARY_VERSION__", perspAppliedBy, out var perspRefusal)) {
              logger?.LogWarning("Perspective {Perspective}: not applied: {Reason}", name, perspRefusal);
              return;
            }
          }

          var tableExisted = false;
          await _underSavepointAsync(connection, "whizbang_perspective",
            () => _applySchemaSqlAsync(dbContext, segmentConnectionFactory, sql, logger, ct),
            ex => {
              if (ex is Npgsql.PostgresException { SqlState: "42P07" } existing) {
                tableExisted = true;
                logger?.LogDebug("Perspective table already exists (expected): {Table}", existing.TableName ?? "unknown");
              } else {
                System.Runtime.ExceptionServices.ExceptionDispatchInfo.Throw(ex);
              }
            }, ct);
          if (!pass.Tracked) {
            return;
          }

          var isUpdate = existingHash != null;
          var (status, desc) = tableExisted
            ? (3, "Skipped (table already exists)")
            : (isUpdate ? 2 : 1, isUpdate ? $"Updated from hash {_hashPrefix(existingHash!)}..." : "First apply");
          await _upsertMigrationAsync(connection, perspectiveKey, hash, pass.VersionId, status, desc, order, "perspective", ct);
          logger?.LogDebug("Perspective {Perspective}: {Status}", name, desc);
        },
        pass.Tracked ? (ex, ct) => _recordFailureAsync(connection, perspectiveKey, hash, pass.VersionId, order, "perspective", ex, ct) : null,
        cancellationToken);
    }
  }

